import { app, BrowserWindow } from 'electron';
import assert from 'node:assert/strict';
import { join } from 'node:path';
import { mkdtempSync, writeFileSync } from 'node:fs';
import { ComfyHost } from '../../src/desktop/comfy-host.js';
import { projectDirectory } from '../../src/core/paths.js';
import type { AppSnapshot } from '../../src/shared/types.js';
import type { GraphView, EditReceipt } from '../../src/shared/comfy.js';
import { createServer } from 'node:net';

const root = process.argv[2], proof = projectDirectory(root, '.runtime', 'comfy-graph-proof');
for (const name of ['appData', 'userData', 'sessionData', 'temp', 'crashDumps'] as const) app.setPath(name, projectDirectory(root, '.runtime', 'comfy-graph-proof', name));
app.setAppLogsPath(projectDirectory(root, '.runtime', 'comfy-graph-proof', 'logs'));
app.commandLine.appendSwitch('disk-cache-dir', projectDirectory(root, '.runtime', 'comfy-graph-proof', 'cache'));
app.disableHardwareAcceleration();
const projectId = 'task-3a-native', project = { id: projectId, root, template: 'comfyui' };
let host: ComfyHost | undefined, window: BrowserWindow | undefined;
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));
app.whenReady().then(async () => {
  window = new BrowserWindow({ show: false, width: 1440, height: 1000, webPreferences: { offscreen: true, sandbox: true, contextIsolation: true, nodeIntegration: false } });
  await window.loadURL('data:text/html,<title>Isolated Comfy graph proof</title>');
  host = new ComfyHost(window, join(root, 'dist/client/comfy'), join(root, 'dist/client/desktop/comfy-preload.cjs'));
  const coldProject = { id: 'close-during-port', root: mkdtempSync(join(proof, 'close-during-port-')), template: 'comfyui' };
  host.observe({ projects: [coldProject], selected: { project: coldProject } } as AppSnapshot);
  const coldStart = host.present(coldProject.id, 1, { x: 0, y: 0, width: 1400, height: 940 }).then(() => null, error => error);
  const coldClose = host.close(coldProject.id);
  try { assert.throws(() => host!.recovery(coldProject.id), /关闭/, 'a closing startup must retain ownership and reject reopening'); }
  finally { await coldClose; await coldStart; }
  assert.match(String(await coldStart), /关闭/);
  assert.deepEqual(host.recovery(coldProject.id), []);
  await host.close(coldProject.id);
  console.log('lifecycle: close during initial port allocation passed');
  host.observe({ projects: [project], selected: { project } } as AppSnapshot);
  const summary = await host.request(projectId, { type: 'summary' });
  assert.equal((summary as any).runtime.status, 'unprepared');
  assert.equal((host as any).entries.get(projectId).start, undefined, 'context must not start the runtime');
  const read = () => host!.request(projectId, { type: 'read_graph' }) as Promise<GraphView>;
  const before = await read(); console.log('initial native graph nodes', (before.workflow.nodes as any[]).length);
  const catalog = await host.request(projectId, { type: 'inspect_nodes', nodeTypes: ['EmptyLatentImage', 'MixcatAPIText', 'NotAnInstalledNode'] }) as any;
  assert.deepEqual(catalog.nodes.map((node: any) => node.classType), ['EmptyLatentImage', 'MixcatAPIText']);
  assert.deepEqual(catalog.nodes[0].outputs, ['LATENT']);
  assert.ok(catalog.nodes[0].inputs.required.width);
  assert.deepEqual(catalog.missing, ['NotAnInstalledNode']);
  assert.equal((await host.request(projectId, { type: 'summary' }) as any).runtime.status, 'ready');
  const originalFetch = globalThis.fetch;
  let releaseCatalog!: () => void, catalogReached!: () => void;
  const gate = new Promise<void>(resolve => { releaseCatalog = resolve; }), reached = new Promise<void>(resolve => { catalogReached = resolve; });
  globalThis.fetch = async (input, init) => { if (String(input).includes('/object_info/')) { catalogReached(); await gate; } return originalFetch(input, init); };
  const inspecting = host.request(projectId, { type: 'inspect_nodes', nodeTypes: ['EmptyLatentImage'] });
  try { await reached; assert.equal((await host.request(projectId, { type: 'summary' }) as any).runtime.status, 'ready'); }
  finally { releaseCatalog(); globalThis.fetch = originalFetch; await inspecting; }
  await host.present(projectId, 1, { x: 0, y: 0, width: 1400, height: 940 });
  const entry = () => (host as any).entries.get(projectId);
  const guest = (code: string) => entry().view.webContents.executeJavaScript(code).catch((error: Error) => { console.error('guest failed:', code); throw error; });
  const messages: string[] = []; entry().view.webContents.on('console-message', (event: any) => { messages.push(event.message); console.log('guest console', event.message); });
  assert.deepEqual(await guest('({ require: typeof require, mixcat: typeof window.mixcat })'), { require: 'undefined', mixcat: 'undefined' });
  await assert.rejects(guest('window.mixcatComfy.connect("wrong-instance")'), /握手/);
  await guest('window.nativeApp=window.comfyAPI.app.app; true');
  await guest('nativeApp.rootGraph.clear(); nativeApp.rootGraph.add(window.LiteGraph.createNode("EmptyLatentImage")); true');
  let view = await read(); assert.equal((view.workflow.nodes as any[]).length, 1);
  const workflow = structuredClone(view.workflow); (workflow.nodes as any[])[0].title = 'Durable native edit';
  const receipt = await host.request(projectId, { type: 'apply_graph', requestId: 'apply-' + Date.now(), expected: view.observation, workflow }) as EditReceipt;
  view = await read(); assert.equal((view.workflow.nodes as any[])[0].title, 'Durable native edit');
  await host.request(projectId, { type: 'restore_graph', requestId: 'restore-' + Date.now(), expected: view.observation, versionId: receipt.beforeVersionId });
  view = await read(); assert.notEqual((view.workflow.nodes as any[])[0].title, 'Durable native edit');
  const stale = view;
  await guest('nativeApp.rootGraph.nodes[0].title="Manual edit"');
  await assert.rejects(host.request(projectId, { type: 'apply_graph', requestId: 'stale-' + Date.now(), expected: stale.observation, workflow }), /变更/);
  await guest('window.firstWorkflow=nativeApp.extensionManager.workflow.activeWorkflow; window.firstData=nativeApp.rootGraph.serialize(); true');
  const tabBefore = await read();
  await guest('nativeApp.loadGraphData({nodes:[],links:[],groups:[],config:{},extra:{},version:0.4},true,false,"ProofSecond").then(()=>true)');
  assert.notEqual((await read()).observation.tabId, tabBefore.observation.tabId);
  const tabPoint = await guest('(()=>{ const button=[...document.querySelectorAll("[role=tab]")].find(e=>e.id.endsWith(window.firstWorkflow.path));button.scrollIntoView();const r=button.getBoundingClientRect();return {x:Math.round(r.x+r.width/2),y:Math.round(r.y+r.height/2)} })()');
  entry().view.webContents.sendInputEvent({ type: 'mouseDown', button: 'left', clickCount: 1, ...tabPoint });
  entry().view.webContents.sendInputEvent({ type: 'mouseUp', button: 'left', clickCount: 1, ...tabPoint });
  for (let i = 0; i < 50 && (await read()).observation.tabId !== tabBefore.observation.tabId; i++) await delay(100);
  assert.equal((await read()).observation.tabId, tabBefore.observation.tabId);
  await assert.rejects(host.request(projectId, { type: 'apply_graph', requestId: 'tab-stale-' + Date.now(), expected: tabBefore.observation, workflow }), /变更/);
  await guest('nativeApp.rootGraph.convertToSubgraph(new Set(nativeApp.rootGraph.nodes)); true');
  await guest('window.subgraphNode=nativeApp.rootGraph.nodes.find(n=>n.subgraph); nativeApp.canvas.openSubgraph(subgraphNode.subgraph,subgraphNode);true');
  await guest('nativeApp.canvas.selectNode(nativeApp.canvas.graph.nodes[0]); true');
  const subgraph = await read(); assert.equal(subgraph.subgraphPath.length, 1); assert.equal((subgraph.workflow.nodes as any[]).length, 1);
  assert.deepEqual(subgraph.selectedNodeIds, ['1']); assert.equal((subgraph.workflow.nodes as any[])[0].id, 2);
  const subgraphEdit = structuredClone(subgraph.workflow); (subgraphEdit.definitions as any).subgraphs[0].nodes[0].title = 'Edited from subgraph';
  const subReceipt = await host.request(projectId, { type: 'apply_graph', requestId: 'sub-' + Date.now(), expected: subgraph.observation, workflow: subgraphEdit }) as EditReceipt;
  assert.equal(((await read()).workflow.definitions as any).subgraphs[0].nodes[0].title, 'Edited from subgraph');
  await host.request(projectId, { type: 'restore_graph', requestId: 'sub-restore-' + Date.now(), expected: (await read()).observation, versionId: subReceipt.beforeVersionId });
  await guest('nativeApp.registerExtension({ name:"Mixcat.ProofRace", beforeConfigureGraph(){ if(window.injectGraphRace){ window.injectGraphRace=false; nativeApp.rootGraph.nodes[0].title="Concurrent native edit"; } } }); true');
  const raceBefore = await read(), raceId = 'race-' + Date.now();
  await guest('window.injectGraphRace=true');
  const raceRequest = { type: 'apply_graph' as const, requestId: raceId, expected: raceBefore.observation, workflow: raceBefore.workflow };
  await assert.rejects(host.request(projectId, raceRequest), /加载失败|变更/);
  const recovery = host.recovery(projectId).find(item => item.requestId === raceId); assert(recovery);
  await assert.rejects(host.request(projectId, raceRequest), /恢复/);
  await host.request(projectId, { type: 'restore_graph', requestId: 'race-restore-' + Date.now(), expected: (await read()).observation, versionId: recovery.beforeVersionId });
  await guest('nativeApp.extensionManager.workflow.saveWorkflow(nativeApp.extensionManager.workflow.activeWorkflow).then(()=>true)');
  const alien = new BrowserWindow({ show: false, webPreferences: { offscreen: true, sandbox: true, contextIsolation: true, nodeIntegration: false, preload: join(root, 'dist/client/desktop/comfy-preload.cjs') } });
  await alien.loadURL('data:text/html,Untrusted guest');
  await assert.rejects(alien.webContents.executeJavaScript(`window.mixcatComfy.connect(${JSON.stringify(entry().instanceId)})`), /来源/); alien.destroy();
  await host.present(projectId, 2, { x: 0, y: 0, width: 1400, height: 940 });
  await delay(500);
  console.log('capture-state', entry().view.getVisible(), entry().view.getBounds(), window.isVisible());
  entry().view.webContents.startPainting(); entry().view.webContents.invalidate(); await delay(1000);
  writeFileSync(join(proof, 'native-graph.png'), (await entry().view.webContents.capturePage(undefined, { stayHidden: true, stayAwake: true })).toPNG());
  const final = await read(), origin = entry().origin, tabs = await guest('nativeApp.extensionManager.workflow.openWorkflows.map(w=>w.path)');
  const oldContents = entry().view.webContents;
  await delay(300);
  const nativeFetch = globalThis.fetch;
  let refusedStopChecks = 0;
  globalThis.fetch = async (input, init) => { if (String(input) === origin + '/queue') { refusedStopChecks++; return new Response('Queue unavailable', { status: 503 }); } return nativeFetch(input, init); };
  try {
    await assert.rejects(host.close(projectId), /拒绝停止/);
    assert.throws(() => host!.recovery(projectId), /关闭/, 'failed stop must retain ownership and prevent replacement');
    assert.equal((await nativeFetch(origin + '/system_stats')).status, 200, 'failed stop leaves the owned runtime alive');
    host.observe({ projects: [], selected: null } as unknown as AppSnapshot);
    oldContents.emit('render-process-gone', {}, { reason: 'crashed', exitCode: 1 }); await delay(20);
    assert.equal(refusedStopChecks, 1, 'snapshot and renderer callbacks must not implicitly retry a failed close');
    host.observe({ projects: [project], selected: { project } } as AppSnapshot);
  } finally { globalThis.fetch = nativeFetch; }
  await host.close(projectId);
  await assert.rejects(nativeFetch(origin + '/system_stats', { signal: AbortSignal.timeout(1000) }), 'retry must stop the retained runtime');
  console.log('lifecycle: failed stop retained ownership and successful close retry passed');
  const occupied = createServer(); await new Promise<void>((resolve, reject) => { occupied.once('error', reject); occupied.listen(Number(new URL(origin).port), '127.0.0.1', resolve); });
  await assert.rejects(read(), /EADDRINUSE|占用/);
  await host.close(projectId);
  await new Promise<void>((resolve, reject) => occupied.close(error => error ? reject(error) : resolve()));
  let releaseStart!: () => void, enteredStart!: () => void;
  const startGate = new Promise<void>(resolve => { releaseStart = resolve; }), startEntered = new Promise<void>(resolve => { enteredStart = resolve; });
  globalThis.fetch = async (input, init) => { if (String(input) === origin + '/system_stats') { enteredStart(); await startGate; } return nativeFetch(input, init); };
  const delayedStart = read().then(() => null, error => error);
  let closingStart: Promise<void> | undefined;
  try {
    await Promise.race([startEntered, delay(30000).then(() => { throw Error('Runtime health gate was not reached'); })]);
    closingStart = host.close(projectId);
    assert.throws(() => host!.recovery(projectId), /关闭/, 'an in-flight runtime must not overlap a replacement');
  } finally { releaseStart(); globalThis.fetch = nativeFetch; await closingStart; }
  assert.match(String(await delayedStart), /关闭/);
  await assert.rejects(nativeFetch(origin + '/system_stats', { signal: AbortSignal.timeout(1000) }));
  console.log('lifecycle: close during delayed runtime startup settled before reopen');
  const reopened = await read(); assert.equal(entry().origin, origin); assert.notEqual(reopened.observation.instanceId, final.observation.instanceId);
  oldContents.emit('render-process-gone', {}, { reason: 'crashed', exitCode: 1 });
  await delay(20);
  assert.equal((await read()).observation.instanceId, reopened.observation.instanceId, 'obsolete renderer event must not close replacement');
  console.log('lifecycle: obsolete renderer callback cannot close replacement');
  assert.deepEqual(reopened.workflow.nodes, final.workflow.nodes);
  assert.deepEqual(reopened.workflow.definitions, final.workflow.definitions);
  assert.deepEqual(await guest('window.comfyAPI.app.app.extensionManager.workflow.openWorkflows.map(w=>w.path)'), tabs);
  assert(host.recovery(projectId).some(item => item.requestId === raceId));
  await host.present(projectId, 3, { x: 0, y: 0, width: 1400, height: 940 });
  entry().view.webContents.startPainting(); entry().view.webContents.invalidate(); await delay(1000);
  writeFileSync(join(proof, 'native-reopened.png'), (await entry().view.webContents.capturePage(undefined, { stayHidden: true, stayAwake: true })).toPNG());
  writeFileSync(join(proof, 'evidence.json'), JSON.stringify({ passed: true, before, receipt, subgraph, subReceipt, recovery, final, reopened, origin, tabs, messages, lifecycle: ['close during port allocation', 'failed stop retains live ownership and close retry succeeds', 'close waits for delayed runtime startup', 'obsolete renderer callback cannot close replacement'], electron: process.versions.electron }, null, 2));
  await host.dispose(); host = undefined; window.destroy(); app.quit();
}).catch(async error => { console.error(error); if (host) await host.dispose().catch(console.error); window?.destroy(); app.exit(1); });
